async markAuthorizing(intentId: string, retainedOperation = false,futureCheckout?:{checkoutId:string;transactionId:string}): Promise<void> {
        if(futureCheckout){
            if(retainedOperation||!this.isEnabled())throw new Error('PAYMENT_INTENT_RECONCILIATION_REQUIRED');
            const result=await this.database.executeSQL!(`UPDATE payment_intents_v2 SET status='AUTHORIZING',updated_at=? WHERE intent_id=? AND status='CREATED' AND transaction_id=?
             AND EXISTS(SELECT 1 FROM pos_fiscal_checkouts_v2 c JOIN pos_fiscal_checkout_current_v2 p ON p.checkout_id=c.checkout_id
              WHERE c.checkout_id=? AND c.transaction_id=payment_intents_v2.transaction_id AND c.phase='EFFECT_POSSIBLE'
              AND EXISTS(SELECT 1 FROM json_each(c.checkout_json,'$.paymentIds') refs WHERE refs.value=payment_intents_v2.payment_id))`,[new Date().toISOString(),intentId,futureCheckout.transactionId,futureCheckout.checkoutId]);
            if(Number(result?.changes?.changes)!==1)throw new Error('PAYMENT_INTENT_RECONCILIATION_REQUIRED');return;
        }
        if (retainedOperation) {
            if (!this.isEnabled()) throw new Error('PAYMENT_INTENT_NATIVE_REQUIRED');
            const result = await this.database.executeSQL!(`UPDATE payment_intents_v2 SET status='AUTHORIZING',updated_at=? WHERE intent_id=? AND status='CREATED'
              AND EXISTS (SELECT 1 FROM documents c JOIN documents r ON r.collection_name='reservations'
                AND r.doc_id=json_extract(c.data,'$.sourceId') WHERE c.collection_name='v3RestoredTicketSources'
                AND json_extract(c.data,'$.sourceCollection')='reservations' AND json_extract(c.data,'$.state')='PENDING'
                AND substr(payment_intents_v2.payment_id,1,length(c.doc_id)+9)=c.doc_id || ':payment:'
                AND r.data=json_extract(c.data,'$.sourceExpected') AND json_extract(r.data,'$.status')='ACTIVE'
                AND julianday(json_extract(r.data,'$.expiryDate'))>julianday('now'))`,[new Date().toISOString(),intentId]);
            if (Number(result?.changes?.changes) !== 1) throw new Error('PAYMENT_INTENT_RECONCILIATION_REQUIRED');
            return;
        }
        await this.update(intentId, 'AUTHORIZING');
    }

methods.commitFinancialTransaction:
async commitFinancialTransaction(input: FinancialCommitInput): Promise<void> {
        const now = new Date().toISOString();
        const statements: Array<{ statement: string; values: any[] }> = [];

        for (const mutation of input.documents) {
            const document = mutation.document;
            if (!document?.id || !mutation.collectionName) {
                throw new Error('Financial commit contains a document without collection or id.');
            }
            statements.push({
                statement: DOCUMENT_UPSERT_SQL,
                values: [
                    mutation.collectionName,
                    String(document.id),
                    JSON.stringify(document),
                    mutation.collectionName,
                    String(document.id),
                    mutation.collectionName,
                    now,
                ],
            });
        }

        const outboxEvents = [input.outboxEvent, ...(input.additionalOutboxEvents || [])];
        for (const event of outboxEvents) {
            statements.push({
                statement: `INSERT INTO sync_outbox_v2 (
                    event_id, event_type, aggregate_type, aggregate_id, schema_version,
                    payload_json, status, attempt_count, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, 'PENDING', 0, ?, ?)
                ON CONFLICT(event_id) DO NOTHING`,
                values: [
                    event.eventId,
                    event.eventType,
                    event.aggregateType,
                    event.aggregateId,
                    event.schemaVersion,
                    JSON.stringify(event.payload),
                    event.createdAt,
                    now,
                ],
            });
        }

        const event = input.outboxEvent;
        for (const intentId of input.paymentIntentIds || []) {
            statements.push({
                statement: `UPDATE payment_intents_v2
                    SET status = 'COMMITTED', transaction_id = ?, committed_at = ?, updated_at = ?, last_error = NULL
                    WHERE intent_id = ? AND status = 'AUTHORIZED'`,
                values: [event.aggregateId, now, now, intentId],
            });
        }

        const needsFinancialPrecondition = input.documents.some(row => row.document.v3InventoryBaseline
          || row.requireAbsent || row.expectedDocument !== undefined || row.v3StockRequirements);
        await this.withWriteLock(() => this.executeUnlocked(statements,async()=>{
          if(needsFinancialPrecondition)await this.assertV3FinancialBaseline(input.documents);
          const births=outboxEvents.filter(e=>e.eventType==='SALE_POSTED'&&e.payload.fiscalWorkflowBirth);
          if(births.some(e=>!input.fiscalWorkflowCommits?.some(c=>c.transactionId===e.aggregateId&&JSON.stringify(c.birth)===JSON.stringify(e.payload.fiscalWorkflowBirth))))throw Error('FISCAL_WORKFLOW_ATOMIC_BIRTH_REQUIRED');
          for(const commit of input.fiscalWorkflowCommits||[]){
            const source=input.documents.find(d=>d.collectionName==='transactions'&&d.document.id===commit.transactionId);
            const history=input.documents.find(d=>d.collectionName==='transactionHistory'&&d.document.id===commit.transactionId);
            if(!source?.requireAbsent||!history?.requireAbsent)throw Error('FISCAL_WORKFLOW_NEW_SOURCE_REQUIRED');
            await consumeFiscalWorkflowBirth(this.ensureDb() as any,commit,source.document as any);
          }
        }));
    }

methods.reserveCheckout:
async reserveCheckout(scopeKey:string,cartIdentity:string,selection?:{operationKind:'RETURN'|'VOID';originalReference:NonNullable<FiscalWorkflowPermitV2['originalReference']>},operationId?:string,options?:FiscalWorkflowReserveOptions):Promise<FiscalWorkflowCheckoutV2>{return this.transaction(async sql=>{
 const current=one(await sql.query('SELECT c.checkout_json,c.checkout_id,c.transaction_id,c.scope_key,c.cart_identity,c.phase,c.permit_id FROM pos_fiscal_checkout_current_v2 p JOIN pos_fiscal_checkouts_v2 c ON c.checkout_id=p.checkout_id WHERE p.scope_key=?',[scopeKey]));
 if(options?.expectedCurrent!==undefined){
  const expected=options.expectedCurrent;let retained:FiscalWorkflowCheckoutV2|null=null;
  try{retained=current?JSON.parse(current.checkout_json):null;}catch{/* Invalid proof remains held. */}
  if(!matchesPreparedRecovery(retained,expected)||expected.scopeKey!==scopeKey||expected.cartIdentity!==cartIdentity||expected.operationId!==operationId
    ||current.checkout_id!==expected.checkoutId||current.transaction_id!==expected.transactionId||current.scope_key!==expected.scopeKey
    ||current.cart_identity!==expected.cartIdentity||current.phase!=='PREPARED')throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');
  if(options.requirePermit!==true||!hasPreparedSalePermit(retained!,scopeKey,options.authorityHash))throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');
  const permit=one(await sql.query('SELECT * FROM pos_fiscal_permits_v2 WHERE permit_id=?',[retained!.permit!.permitId]));
  if(!permit||current.permit_id!==retained!.permit!.permitId||permit.checkout_id!==expected.checkoutId||permit.transaction_id!==expected.transactionId
    ||permit.scope_key!==expected.scopeKey||permit.state!=='RESERVED'||JSON.stringify(JSON.parse(permit.permit_json))!==JSON.stringify(retained!.permit))throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');
 }
 if(current){const checkout=JSON.parse(current.checkout_json) as FiscalWorkflowCheckoutV2;if(checkout.phase==='ACKNOWLEDGED'&&operationId&&checkout.operationId!==operationId){await sql.run('DELETE FROM pos_fiscal_checkout_current_v2 WHERE scope_key=? AND checkout_id=?',[scopeKey,checkout.checkoutId],false);}else{if(operationId&&checkout.operationId!==operationId&&!['COMMITTED','ACKNOWLEDGED'].includes(checkout.phase))throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');if(selection&&(checkout.permit?.operationKind!==selection.operationKind||JSON.stringify(checkout.permit?.originalReference)!==JSON.stringify(selection.originalReference)))throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');if(options?.requirePermit&&!checkout.permit)throw Error('FISCAL_WORKFLOW_PERMIT_REQUIRED');if(options?.requirePermit&&!['COMMITTED','ACKNOWLEDGED'].includes(checkout.phase)&&(!options.authorityHash||checkout.permit?.authorityHash!==options.authorityHash||!Number.isFinite(Date.parse(checkout.permit?.expiresAt||''))||Date.parse(checkout.permit?.expiresAt||'')<=Date.now()))throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');if(checkout.cartIdentity!==cartIdentity&&checkout.phase!=='COMMITTED')throw Error('FISCAL_WORKFLOW_CHECKOUT_RECONCILIATION_REQUIRED');return checkout;}}
 if(options?.requirePermit&&!options.authorityHash)throw Error('FISCAL_WORKFLOW_PERMIT_REQUIRED');
 const pool=one(await sql.query("SELECT * FROM pos_fiscal_permits_v2 WHERE scope_key=? AND state='AVAILABLE' AND expires_at>? AND json_extract(permit_json,'$.operationKind')=? AND (? IS NULL OR json_extract(permit_json,'$.originalReference')=json(?)) AND (? IS NULL OR json_extract(permit_json,'$.authorityHash')=?) ORDER BY expires_at,permit_id LIMIT 1",[scopeKey,new Date().toISOString(),selection?.operationKind||'SALE',selection?JSON.stringify(selection.originalReference):null,selection?JSON.stringify(selection.originalReference):null,options?.authorityHash||null,options?.authorityHash||null]));
 if(selection&&!pool)throw Error('FISCAL_WORKFLOW_REFERENCED_PERMIT_REQUIRED');
 if(options?.requirePermit&&!pool)throw Error('FISCAL_WORKFLOW_PERMIT_REQUIRED');
 const permit=pool?JSON.parse(pool.permit_json) as FiscalWorkflowPermitV2:null,checkout:FiscalWorkflowCheckoutV2={checkoutId:createUuid(),operationId:operationId||createUuid(),transactionId:permit?.transactionId||createUuid(),scopeKey,cartIdentity,permit,phase:'PREPARED',paymentIds:[]};
 if(permit){await sql.run("UPDATE pos_fiscal_permits_v2 SET state='RESERVED',checkout_id=? WHERE permit_id=? AND state='AVAILABLE'",[checkout.checkoutId,permit.permitId],false);if(Number(one(await sql.query('SELECT changes() count'))?.count)!==1)fail();}
 await sql.run('INSERT INTO pos_fiscal_checkouts_v2(checkout_id,transaction_id,scope_key,cart_identity,permit_id,checkout_json,phase)VALUES(?,?,?,?,?,?,?)',[checkout.checkoutId,checkout.transactionId,scopeKey,cartIdentity,permit?.permitId||null,JSON.stringify(checkout),checkout.phase],false);await sql.run('INSERT INTO pos_fiscal_checkout_current_v2(scope_key,checkout_id)VALUES(?,?)',[scopeKey,checkout.checkoutId],false);return checkout;});}

schema:
CREATE TABLE IF NOT EXISTS pos_fiscal_permits_v2(permit_id TEXT PRIMARY KEY,transaction_id TEXT NOT NULL UNIQUE,scope_key TEXT NOT NULL,permit_json TEXT NOT NULL,expires_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('AVAILABLE','RESERVED','CONSUMED')),checkout_id TEXT UNIQUE);
CREATE INDEX IF NOT EXISTS pos_fiscal_permits_pool_v2 ON pos_fiscal_permits_v2(scope_key,state,expires_at);
CREATE TABLE IF NOT EXISTS pos_fiscal_checkouts_v2(checkout_id TEXT PRIMARY KEY,transaction_id TEXT NOT NULL UNIQUE,scope_key TEXT NOT NULL,cart_identity TEXT NOT NULL,permit_id TEXT UNIQUE,checkout_json TEXT NOT NULL,phase TEXT NOT NULL CHECK(phase IN ('PREPARED','EFFECT_POSSIBLE','COMMITTED','ACKNOWLEDGED')));
CREATE TABLE IF NOT EXISTS pos_fiscal_checkout_current_v2(scope_key TEXT PRIMARY KEY,checkout_id TEXT NOT NULL REFERENCES pos_fiscal_checkouts_v2(checkout_id));
CREATE TABLE IF NOT EXISTS pos_fiscal_watch_v2(transaction_id TEXT PRIMARY KEY,scope_key TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS pos_fiscal_watch_scope_v2 ON pos_fiscal_watch_v2(scope_key,transaction_id);
CREATE TABLE IF NOT EXISTS pos_fiscal_refill_v2(scope_key TEXT PRIMARY KEY,operation_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pos_fiscal_state_v2(transaction_id TEXT PRIMARY KEY,scope_key TEXT NOT NULL,source_identity TEXT NOT NULL,source_original TEXT NOT NULL,state_json TEXT NOT NULL,version INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS pos_fiscal_state_candidates_v2 ON pos_fiscal_state_v2(scope_key,transaction_id);
CREATE TRIGGER IF NOT EXISTS pos_fiscal_permit_identity_v2 BEFORE UPDATE ON pos_fiscal_permits_v2 WHEN OLD.permit_id IS NOT NEW.permit_id OR OLD.transaction_id IS NOT NEW.transaction_id OR OLD.scope_key IS NOT NEW.scope_key OR OLD.permit_json IS NOT NEW.permit_json OR OLD.expires_at IS NOT NEW.expires_at OR OLD.state='CONSUMED' AND NEW.state<>'CONSUMED' OR OLD.checkout_id IS NOT NULL AND OLD.checkout_id IS NOT NEW.checkout_id BEGIN SELECT RAISE(ABORT,'FISCAL_WORKFLOW_PERMIT_IMMUTABLE');END;
CREATE TRIGGER IF NOT EXISTS pos_fiscal_checkout_identity_v2 BEFORE UPDATE ON pos_fiscal_checkouts_v2 WHEN OLD.checkout_id IS NOT NEW.checkout_id OR OLD.transaction_id IS NOT NEW.transaction_id OR OLD.scope_key IS NOT NEW.scope_key OR OLD.cart_identity IS NOT NEW.cart_identity OR OLD.permit_id IS NOT NEW.permit_id OR OLD.phase IN ('COMMITTED','ACKNOWLEDGED') AND NEW.phase NOT IN ('COMMITTED','ACKNOWLEDGED') BEGIN SELECT RAISE(ABORT,'FISCAL_WORKFLOW_CHECKOUT_IMMUTABLE');END;
CREATE TRIGGER IF NOT EXISTS pos_fiscal_permit_delete_v2 BEFORE DELETE ON pos_fiscal_permits_v2 BEGIN SELECT RAISE(ABORT,'FISCAL_WORKFLOW_DURABLE_IDENTITY');END;
CREATE TRIGGER IF NOT EXISTS pos_fiscal_checkout_delete_v2 BEFORE DELETE ON pos_fiscal_checkouts_v2 BEGIN SELECT RAISE(ABORT,'FISCAL_WORKFLOW_DURABLE_IDENTITY');END;
CREATE TRIGGER IF NOT EXISTS pos_fiscal_state_delete_v2 BEFORE DELETE ON pos_fiscal_state_v2 BEGIN SELECT RAISE(ABORT,'FISCAL_WORKFLOW_DURABLE_IDENTITY');END;
CREATE TRIGGER IF NOT EXISTS pos_fiscal_state_identity_v2 BEFORE UPDATE ON pos_fiscal_state_v2 WHEN OLD.transaction_id IS NOT NEW.transaction_id OR OLD.scope_key IS NOT NEW.scope_key OR OLD.source_identity IS NOT NEW.source_identity OR OLD.source_original IS NOT NEW.source_original OR NEW.version<=OLD.version BEGIN SELECT RAISE(ABORT,'FISCAL_WORKFLOW_SIDECAR_CAS');END;
